{
  "query": "mutation LOGIN($userName: String!, $password: String!) { login(data: { userName: $userName, password: $password }) { userId } }",
  "variables": {
    "userName": "elisa.pereira",
    "password": "Senha123"
  }
}

{
  "query": "mutation { login(data: { userName: \"elisa.pereira\", password: \"SenhaErrada1\" }) { userId } }"
}

{
  "query": "query GET_USER($id: ID!) { user(id: $id) { id firstName lastName userName indexRef createdAt posts { id title } } }",
  "variables": { "id": "602" }
}

{
  "query": "query GET_USERS($input: ApiFiltersInput) { users(input: $input) { id firstName lastName userName indexRef createdAt } }",
  "variables": {
    "input": {
      "_sort": "index_ref",
      "_order": "ASC",
      "_start": 0,
      "_limit": 5
    }
  }
}

{
  "query": "query { users { id userName } }"
}

{
  "query": "mutation CREATE_USER($data: CreateUserInput!) { createUser(data: $data) { id firstName lastName userName indexRef createdAt } }",
  "variables": {
    "data": {
      "firstName": "Test",
      "lastName": "User",
      "userName": "test.user99",
      "password": "Senha123"
    }
  }
}

{
  "query": "mutation { createUser(data: { firstName: \"Dup\", lastName: \"User\", userName: \"elisa.pereira\", password: \"Senha123\" }) { id } }"
}

{
  "query": "mutation UPDATE_USER($userId: ID!, $data: UpdateUserInput!) { updateUser(userId: $userId, data: $data) { id firstName lastName userName } }",
  "variables": {
    "userId": "602",
    "data": {
      "firstName": "Elisa Updated"
    }
  }
}

{
  "query": "mutation { updateUser(userId: \"903\", data: { firstName: \"Hack\" }) { id } }"
}

{
  "query": "mutation DELETE_USER($userId: ID!) { deleteUser(userId: $userId) }",
  "variables": {
    "userId": "{{createdUserId}}"
  }
}

{
  "query": "query GET_POST($id: ID!) { post(id: $id) { id title body indexRef createdAt user { id firstName lastName userName } comments { id comment createdAt user { userName } } } }",
  "variables": { "id": "645" }
}

{
  "query": "query GET_POSTS($input: ApiFiltersInput) { posts(input: $input) { id title body indexRef createdAt user { userName } } }",
  "variables": {
    "input": {
      "_sort": "created_at",
      "_order": "DESC",
      "_limit": 3
    }
  }
}

{
  "query": "mutation CREATE_POST($data: CreatePostInput!) { createPost(data: $data) { id title body indexRef createdAt user { id userName } } }",
  "variables": {
    "data": {
      "title": "My new post via Postman",
      "body": "Content of the post created by the test collection."
    }
  }
}

{
  "query": "mutation { createPost(data: { title: \"Hack\", body: \"Tentativa sem login\" }) { id } }"
}

{
  "query": "mutation UPDATE_POST($postId: ID!, $data: UpdatePostInput!) { updatePost(postId: $postId, data: $data) { id title body } }",
  "variables": {
    "postId": "{{createdPostId}}",
    "data": {
      "title": "Title Updated via Postman"
    }
  }
}

{
  "query": "mutation { updatePost(postId: \"50\", data: { title: \"Hack\" }) { id } }"
}

{
  "query": "mutation DELETE_POST($postId: ID!) { deletePost(postId: $postId) }",
  "variables": {
    "postId": "{{createdPostId}}"
  }
}

{
  "query": "mutation CREATE_COMMENT($data: CreateCommentInput!) { createComment(data: $data) { id comment createdAt user { id userName } } }",
  "variables": {
    "data": {
      "comment": "Great post! Commented via Postman.",
      "postId": "361"
    }
  }
}

{
  "query": "mutation { createComment(data: { comment: \"Tentativa sem login\", postId: \"361\" }) { id } }"
}

{
  "query": "mutation { createComment(data: { comment: \"Great post! Commented via Postman.\", postId: \"361\" }) { id } }"
}

{
  "query": "query { users(input: { _sort: \"password_hash\" }) { id } }"
}

{
  "query": "query { post(id: \"645\") { user { posts { user { posts { user { posts { user { id } } } } } } } } }"
}

{
  "query": "mutation { login(data: { userName: \"nonexistent.user\", password: \"Senha123\" }) { userId } }"
}

{
  "query": "mutation LOGOUT($userName: String!) { logout(userName: $userName) }",
  "variables": {
    "userName": "elisa.pereira"
  }
}

{
  "query": "mutation { login(data: { userName: \"talita.melo\", password: \"Senha123\" }) { userId } }"
}

{
  "query": "mutation { createPost(data: { title: \"Happy Path Post\", body: \"Content of the full flow.\" }) { id title user { userName } } }"
}

{
  "query": "query($id: ID!) { post(id: $id) { id title body user { userName } comments { id } } }",
  "variables": { "id": "{{createdPostId}}" }
}

{
  "query": "mutation($postId: ID!, $data: UpdatePostInput!) { updatePost(postId: $postId, data: $data) { id title } }",
  "variables": {
    "postId": "{{createdPostId}}",
    "data": { "title": "Post Atualizado — Happy Path" }
  }
}

{
  "query": "mutation($postId: ID!) { deletePost(postId: $postId) }",
  "variables": { "postId": "{{createdPostId}}" }
}

{
  "query": "mutation { logout(userName: \"talita.melo\") }"
}
